# Inhoud voor de cursussen fysica 3NW (optica en krachten) in het nieuwe formaat.
# D(idee, vb, test, wb, letop, stappen, steun): stappen = (titel, [(vraag, uitleg)]) volledig waar de denkstap nieuw is; steun = korte geheugensteun.

def D(idee, vb, test, wb, letop=None, stappen=None, steun=None):
    return dict(idee=idee, vb=vb, test=test, wb=wb, letop=letop, stappen=stappen, steun=steun)

